proof fn lemma_fv_eq_filter(s: Seq<char>, p: spec_fn(char) -> bool)
    requires
        forall|c: char| #[trigger] p(c) == is_lower_vowel(c),
    ensures
        filter_vowels(s) == s.filter(p),
    decreases s.len()
{
    reveal_with_fuel(Seq::filter, 2);
    if s.len() == 0 {
        assert(s =~= Seq::<char>::empty());
    } else {
        let n = s.len() as int;
        let p0 = s.subrange(0, n - 1);
        assert(p0 =~= s.drop_last());
        lemma_fv_eq_filter(p0, p);
        let last = s[n - 1];
        assert(last == s.last());
        assert(vowels().contains(last) == is_lower_vowel(last));
        assert(p(last) == is_lower_vowel(last));
        if vowels().contains(last) {
            assert(p(last));
            assert(filter_vowels(s) == filter_vowels(p0).add(seq![last]));
            assert(s.filter(p) == s.drop_last().filter(p).push(s.last()));
            assert(filter_vowels(p0).add(seq![last]) =~= p0.filter(p).push(last));
        } else {
            assert(!p(last));
            assert(filter_vowels(s) == filter_vowels(p0));
            assert(s.filter(p) == s.drop_last().filter(p));
        }
    }
}
