proof fn lemma_count_eq_k(s: Seq<i8>, f: spec_fn(int, i8) -> int, k: int)
    requires
        0 <= k,
        k <= s.len() as int / 2,
        forall|i: int, x: i8| #[trigger] f(i, x) == x as int,
    ensures
        count_mismatches(s, k) == count_mismatched_pairs_up_to(s.map(f), k),
    decreases k
{
    if k <= 0 {
    } else {
        lemma_count_eq_k(s, f, k - 1);
        let m = s.map(f);
        assert(m.len() == s.len());
        let j = s.len() as int - k;
        assert(0 <= k - 1 < s.len());
        assert(0 <= j < s.len());
        assert(m[k - 1] == f(k - 1, s[k - 1]));
        assert(m[j] == f(j, s[j]));
        assert(f(k - 1, s[k - 1]) == s[k - 1] as int);
        assert(f(j, s[j]) == s[j] as int);
        assert((s[k - 1] != s[j]) == (m[k - 1] != m[j]));
        assert(count_mismatches(s, k) == count_mismatches(s, k - 1) + (if s[k - 1] != s[j] { 1int } else { 0int }));
        assert(count_mismatched_pairs_up_to(m, k) == (if m[k - 1] != m[j] { 1int } else { 0int }) + count_mismatched_pairs_up_to(m, k - 1));
    }
}

proof fn lemma_count_eq_forall(s: Seq<i8>)
