        #[trigger] count_mismatched_pairs(s.map(f)) == count_mismatches(s, s.len() as int / 2) by {
        lemma_count_eq_k(s, f, s.len() as int / 2);
        let m = s.map(f);
        assert(m.len() == s.len());
        assert(count_mismatched_pairs(m) == count_mismatched_pairs_up_to(m, m.len() as int / 2));
    }
}
