proof fn lemma_take_filter_even_helper(s: Seq<u32>, n: int)
    requires
        0 <= n <= s.len(),
        forall|k: int| 0 <= k < n ==> s[k] % 2 == 0,
    ensures
        s.take(n) =~= s.take(n).filter(|x: u32| x % 2 == 0),
    decreases n
{
    reveal(Seq::filter);
    if n > 0 {
        lemma_take_filter_even_helper(s, n - 1);
        let t = s.take(n);
        assert(t.len() == n);
        assert(t.drop_last() =~= s.take(n - 1));
        assert(t.last() == s[n - 1]);
        assert(s[n - 1] % 2 == 0);
        assert(t.drop_last().filter(|x: u32| x % 2 == 0) =~= s.take(n - 1).filter(|x: u32| x % 2 == 0));
        assert(t.filter(|x: u32| x % 2 == 0) =~= t.drop_last().filter(|x: u32| x % 2 == 0).push(t.last()));
        assert(s.take(n - 1).push(s[n - 1]) =~= s.take(n));
    }
}
